ALTER TABLE "standalone_license_issuances" DROP CONSTRAINT "standalone_license_issuances_shape_check";--> statement-breakpoint
ALTER TABLE "catalog_items" ADD COLUMN "offline_available" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "standalone_license_issuances" ADD COLUMN "source_assignments" jsonb;--> statement-breakpoint
ALTER TABLE "catalog_items" ADD CONSTRAINT "catalog_items_offline_kind_check" CHECK ("catalog_items"."offline_available" = false or "catalog_items"."kind" in ('plan', 'addon'));--> statement-breakpoint
ALTER TABLE "standalone_license_issuances" ADD CONSTRAINT "standalone_license_issuances_shape_check" CHECK ("standalone_license_issuances"."sequence" > 0 and "standalone_license_issuances"."grace_days" between 0 and 60 and "standalone_license_issuances"."plan" in ('demo','subscription') and ("standalone_license_issuances"."plan" <> 'demo' or "standalone_license_issuances"."grace_days" = 0) and "standalone_license_issuances"."sha256" ~ '^[0-9a-f]{64}$' and length(btrim("standalone_license_issuances"."kid")) between 1 and 128 and octet_length("standalone_license_issuances"."compact") between 1 and 16384 and "standalone_license_issuances"."entitlement_revision" >= 0 and "standalone_license_issuances"."valid_until_reason" in ('subscription_end','entitlement_reduction','one_year_cap','offline_term') and "standalone_license_issuances"."source" in ('subscription','offline','offline_assignments') and (("standalone_license_issuances"."source" = 'offline') = ("standalone_license_issuances"."valid_until_reason" = 'offline_term')) and ("standalone_license_issuances"."source" not in ('offline','offline_assignments') or "standalone_license_issuances"."plan" = 'subscription') and (("standalone_license_issuances"."source" = 'offline_assignments') = ("standalone_license_issuances"."source_assignments" is not null)) and ("standalone_license_issuances"."source_assignments" is null or (jsonb_typeof("standalone_license_issuances"."source_assignments") = 'array' and jsonb_array_length("standalone_license_issuances"."source_assignments") between 1 and 65)));